<?php use App\Core\Helpers as H; ?>
<h1>Seller Analytics</h1><p class="muted">Only sales, customers, promotions, referrals, and events connected to your seller account are included.</p>
<?php if($error):?><div class="alert error"><?=H::e($error)?></div><?php else:?><form class="card" method="get"><label>From <input type="date" name="from" value="<?=H::e($report['filters']['from'])?>"></label><label>To <input type="date" name="to" value="<?=H::e($report['filters']['to'])?>"></label><button>Apply</button> <a class="btn" href="/seller/analytics.csv?<?=http_build_query($report['filters'])?>">Export CSV</a></form>
<div class="dashboard-grid"><?php foreach(['gross_sales'=>'Gross sales','net_sales'=>'Net sales','seller_earnings'=>'Earnings','discounts'=>'Discounts','refunds'=>'Refunds','orders'=>'Orders'] as $key=>$label):?><div class="card"><strong><?=$key==='orders'?number_format($report['financials'][$key]):H::money($report['financials'][$key])?></strong><span><?=H::e($label)?></span></div><?php endforeach;?></div>
<section class="card"><h2>What this means</h2><ul><?php foreach($report['insights'] as $insight):?><li><?=H::e($insight)?></li><?php endforeach;?></ul></section>
<section class="card"><h2>Period comparison</h2><p class="muted"><?=H::e($report['filters']['from'])?>–<?=H::e($report['filters']['to'])?> compared with the equivalent previous period, <?=H::e($report['filters']['previous_from'])?>–<?=H::e($report['filters']['previous_to'])?>.</p><div class="table-wrap"><table><tr><th>Metric</th><th>Current</th><th>Previous</th><th>Difference</th><th>Change</th></tr><?php foreach(['gross_sales'=>'Gross sales','net_sales'=>'Net sales','seller_earnings'=>'Earnings','discounts'=>'Discounts','refunds'=>'Refunds','orders'=>'Orders'] as $key=>$label):$c=$report['comparisons'][$key];?><tr><th><?=H::e($label)?></th><td><?=H::e((string)$c['current'])?></td><td><?=H::e((string)$c['previous'])?></td><td><?=H::e((string)$c['difference'])?></td><td><?=$c['percent']===null?'Not available — prior value is zero':H::e((string)$c['percent']).'%'?></td></tr><?php endforeach;?></table></div></section>
<?php $tables=[['Revenue by traffic source',$report['traffic_sources'],['traffic_source'=>'Source','orders'=>'Orders','net_revenue'=>'Net revenue']],['Product performance',$report['products'],['title'=>'Product','units'=>'Units','gross_sales'=>'Gross sales']],['Returning customers',$report['customers'],['name'=>'Customer','order_count'=>'Qualifying orders','last_order_at'=>'Last order']],['Coupon performance',$report['coupons'],['code'=>'Code','uses'=>'Uses','discount_amount'=>'Discount']],['Promotion performance',$report['promos'],['placement'=>'Placement','status'=>'Status','campaigns'=>'Campaigns','impressions'=>'Impressions','clicks'=>'Clicks']],['Referral activity',$report['referrals'],['referral_type'=>'Type','referrals'=>'Referrals','rewarded'=>'Rewarded']],['Bundle-event performance',$report['bundles'],['title'=>'Event','orders'=>'Orders','earnings_cents'=>'Earnings (cents)']],['Upcoming collaborative-event drops',$report['scheduled'],['drop_date'=>'Drop date','listing_count'=>'Scheduled events']]];foreach($tables as [$title,$rows,$columns]):?><section class="card"><h2><?=H::e($title)?></h2><?php if(!$rows):?><p class="muted">No data for this period.</p><?php else:?><div class="table-wrap"><table><thead><tr><?php foreach($columns as $heading):?><th><?=H::e($heading)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as $row):?><tr><?php foreach($columns as $key=>$heading):?><td><?=H::e((string)$row[$key])?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php endforeach;?><?php endif;?>
